BEGIN;
DO $test$
#variable_conflict use_variable
DECLARE owner_id uuid; manager_id uuid; gid uuid; other_gid uuid; student uuid; session uuid; package_student uuid; package_session uuid; pending uuid; paid_session uuid; result jsonb; test_date date:=current_date+5;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.app_settings WHERE academy_name LIKE '%STAGING%') THEN RAISE EXCEPTION 'STAGING_MARKER_REQUIRED'; END IF;
 SELECT id INTO owner_id FROM public.user_profiles WHERE phone='01000000531' AND role='owner';
 SELECT id INTO manager_id FROM public.user_profiles WHERE phone='01000000532' AND role='manager';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 INSERT INTO public.groups(code,name,stage,grade,session_price) VALUES('employee-'||gen_random_uuid(),'SYNTHETIC EMPLOYEE','prep','prep_1',20) RETURNING id INTO gid;
 INSERT INTO public.groups(code,name,stage,grade,session_price) VALUES('transfer-'||gen_random_uuid(),'SYNTHETIC TRANSFER','prep','prep_1',20) RETURNING id INTO other_gid;
 INSERT INTO public.students(full_name,group_id,parent_phone,points_balance) VALUES('SYNTHETIC EMPLOYEE STUDENT',gid,'01000000534',199) RETURNING id INTO student;
 PERFORM public.set_manager_points_session_access(gid,test_date,true);
 PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
 result:=public.queue_manager_points_authorized(student,1,'homework','homework','SYNTHETIC homework',test_date);
 IF NOT (result->>'queued')::boolean THEN RAISE EXCEPTION 'EMPLOYEE_QUEUE_FAILED'; END IF;
 pending:=(result->>'pending_id')::uuid;
 PERFORM public.queue_manager_points_authorized(student,1,'homework','homework','SYNTHETIC homework',test_date);
 IF (SELECT count(*) FROM public.pending_session_points WHERE student_id=student)<>1 THEN RAISE EXCEPTION 'EMPLOYEE_RETRY_DUPLICATED_POINTS'; END IF;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 PERFORM public.review_pending_session_point(pending,'approve',1);
 INSERT INTO public.sessions(group_id,session_date,start_time,price) VALUES(gid,test_date,'16:00',20) RETURNING id INTO session;
 PERFORM public.save_safe_attendance_with_account(session,student,'present','paid',0,'[]',NULL);
 paid_session:=session;
 UPDATE public.students SET group_id=other_gid WHERE id=student;
 PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
 PERFORM public.complete_session_with_pending_points(session);
 PERFORM public.complete_session_with_pending_points(session);
 IF (SELECT points_balance FROM public.students WHERE id=student)<>200 THEN RAISE EXCEPTION 'EMPLOYEE_POINTS_DUPLICATED_OR_LOST'; END IF;
 IF (SELECT count(*) FROM public.student_milestone_rewards WHERE student_id=student)<>1 THEN RAISE EXCEPTION 'EMPLOYEE_AWARD_DUPLICATED'; END IF;
 PERFORM public.save_safe_attendance_with_account(session,student,'present','paid',0,'[]',NULL);
 IF (SELECT points_balance FROM public.students WHERE id=student)<>200 THEN RAISE EXCEPTION 'ATTENDANCE_RESAVE_LOST_EMPLOYEE_POINTS'; END IF;
 IF (SELECT count(*) FROM public.payments WHERE student_id=student)<>1 THEN RAISE EXCEPTION 'ATTENDANCE_RESAVE_DUPLICATED_PAYMENT'; END IF;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 INSERT INTO public.sessions(group_id,session_date,start_time,price) VALUES(other_gid,test_date+1,'16:00',20) RETURNING id INTO session;
 PERFORM public.save_safe_attendance_with_account(session,student,'absent','paid',0,'[]',NULL);
 IF (SELECT charge_amount FROM public.attendance WHERE session_id=session AND student_id=student)<>0 THEN RAISE EXCEPTION 'ABSENCE_CHARGED'; END IF;
 INSERT INTO public.students(full_name,group_id,parent_phone,points_balance) VALUES('SYNTHETIC PACKAGE RESTORATION',other_gid,'01000000534',190) RETURNING id INTO package_student;
 PERFORM public.purchase_student_session_package_custom(package_student,'cash',gen_random_uuid(),8);
 INSERT INTO public.sessions(group_id,session_date,start_time,price) VALUES(other_gid,test_date+2,'16:00',20) RETURNING id INTO package_session;
 PERFORM public.save_package_attendance_if_available(package_session,package_student,'present','paid',10,'[]',NULL);
 UPDATE public.attendance SET points_change=points_change+1,points_details=points_details||'[{"value":1,"reason":"homework","source":"manager_pending"}]'::jsonb WHERE session_id=package_session AND student_id=package_student;
 UPDATE public.students SET points_balance=points_balance+1 WHERE id=package_student;
 PERFORM public.save_package_attendance_if_available(package_session,package_student,'present','paid',10,'[{"value":1,"source":"manager_pending"}]',NULL);
 IF (SELECT points_balance FROM public.students WHERE id=package_student)<>201 THEN RAISE EXCEPTION 'PACKAGE_RESAVE_LOST_OR_DUPLICATED_EMPLOYEE_POINTS'; END IF;
 IF (SELECT sessions_remaining FROM public.student_session_packages WHERE student_id=package_student)<>7 THEN RAISE EXCEPTION 'PACKAGE_RETRY_CONSUMED_TWICE'; END IF;
 PERFORM public.save_package_attendance_if_available(package_session,package_student,'absent','free',0,'[]',NULL);
 IF (SELECT sessions_remaining FROM public.student_session_packages WHERE student_id=package_student)<>8 THEN RAISE EXCEPTION 'PACKAGE_NOT_RESTORED'; END IF;
 IF (SELECT points_balance FROM public.students WHERE id=package_student)<>191 THEN RAISE EXCEPTION 'PACKAGE_POINT_REVERSAL_WRONG'; END IF;
 IF (SELECT count(*) FROM public.student_milestone_rewards WHERE student_id=package_student)<>1 THEN RAISE EXCEPTION 'EARNED_PACKAGE_AWARD_REMOVED'; END IF;
 PERFORM public.save_package_attendance_if_available(package_session,package_student,'present','paid',10,'[]',NULL);
 IF (SELECT sessions_remaining FROM public.student_session_packages WHERE student_id=package_student)<>7 THEN RAISE EXCEPTION 'PACKAGE_REENTRY_WRONG'; END IF;
 IF (SELECT points_balance FROM public.students WHERE id=package_student)<>201 THEN RAISE EXCEPTION 'PACKAGE_REENTRY_LOST_EMPLOYEE_POINTS'; END IF;
 IF (SELECT count(*) FROM public.attendance WHERE session_id=package_session AND student_id=package_student)<>1 THEN RAISE EXCEPTION 'DUPLICATE_ATTENDANCE_AFTER_REENTRY'; END IF;
 PERFORM public.purchase_student_session_package_custom(student,'cash',gen_random_uuid(),8);
 result:=public.save_package_attendance_if_available(paid_session,student,'present','paid',0,'[]',NULL);
 IF (result->>'handled')::boolean OR (SELECT sessions_remaining FROM public.student_session_packages WHERE student_id=student)<>8 THEN RAISE EXCEPTION 'CASH_PAID_SESSION_CONSUMED_PACKAGE'; END IF;
 UPDATE public.manager_permissions SET permissions='{}' WHERE user_id=manager_id;
 PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
 BEGIN
  PERFORM public.queue_manager_points_authorized(student,1,'homework','homework','SYNTHETIC denial',test_date+3);
  RAISE EXCEPTION 'EXPECTED_UNAUTHORIZED_MANAGER_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM='EXPECTED_UNAUTHORIZED_MANAGER_REJECTION' THEN RAISE; END IF; END;
END $test$;
SELECT 'PASS: real employee queue/review/retry, transferred student session close, preserved employee points, absence fees and package restore/re-entry with permanent awards' AS result;
ROLLBACK;
